INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('5bdd7aef-132f-4e8a-b0d2-aa007464bbad', 'Emergence of Arthropod and Fish Life', 22, 'POINT', 'STANDARD', NULL, '2026-06-23 18:54:04.800177+00', '2026-06-23 18:54:04.800177+00');
INSERT INTO eras (id, name, order_index, type, importance, description, created_at, updated_at) VALUES ('1cef56ea-c063-423d-8116-02abd1b4ee17', 'Era of Elements', 23, 'ERA', NULL, 'Different planets with different natures, each representing different forces of nature.', '2026-06-23 18:54:04.812994+00', '2026-06-23 18:54:04.812994+00');
